<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
using namespace std;

long long calculate(long long n) {
    if (n == 0) return 0;
    long long base = 1, digits = 1;
    while (base <= n) {
        base = base * 10 + 1;
        digits++;
    }
    digits--;
    base = (base - 1) / 10;
    if (base == n) return digits;
    long long min_moves = (1LL << 62);
    if ((base * 10 + 1 - n) < n) {
        min_moves = calculate(base * 10 + 1 - n) + digits + 1;
    }
    long long multiplier = 1;
    long long candidate_value;
    while (base * multiplier <= n) {
        candidate_value = base * multiplier;
        multiplier++;
    }
    multiplier--;
    long long alternative = calculate(n - candidate_value) + digits * (multiplier - 1);
    return min(min_moves, alternative);
}

int main() {
    ios::sync_with_stdio(false);
    long long val;
    cin >> val;
    cout << calculate(val);
    return 0;
}
